<script setup>
import { $api } from '@/utils/api'
const facilities=ref([]), meta=ref({venues:[],groups:[],tags:[],sport_codes:[]}), error=ref(''), open=ref(false), hoursOpen=ref(false), selected=ref(null)
const blank=()=>({venue_id:null,sport_code_id:null,facility_group_id:null,name:'',code:'',facility_type:'tennis_court',surface_type:'',indoor:false,capacity:4,description:'',booking_instructions:'',access_zone:'',lighting_available:false,publicly_visible:true,bookable:true,active:true,display_order:0,default_duration_minutes:60,start_interval_minutes:30,tag_ids:[]})
const form=reactive(blank()), hours=reactive({day_of_week:1,opens_at:'07:00',closes_at:'21:00',effective_from:null,effective_until:null,active:true})
async function load(){[facilities.value,meta.value]=await Promise.all([$api('/booking/facilities'),$api('/booking/facilities/meta')])}
function create(){Object.assign(form,blank());selected.value=null;open.value=true}
function edit(item){selected.value=item;Object.assign(form,{...blank(),...item,tag_ids:item.tags.map(t=>t.id)});open.value=true}
async function save(){try{await $api(selected.value?`/booking/facilities/${selected.value.id}`:'/booking/facilities',{method:selected.value?'PUT':'POST',body:form});open.value=false;await load()}catch(e){error.value=e?.data?.message||'Facility could not be saved.'}}
async function saveHours(){try{await $api(`/booking/facilities/${selected.value.id}/opening-hours`,{method:'POST',body:hours});hoursOpen.value=false;await load()}catch(e){error.value=e?.data?.message||'Opening hours could not be saved.'}}
onMounted(load)
</script>
<template><div><div class="d-flex justify-space-between align-center mb-6"><div><h3 class="text-h3">Facilities</h3><p class="text-medium-emphasis">Venues, courts, groups, tags and booking configuration.</p></div><VBtn @click="create">Add facility</VBtn></div><VAlert v-if="error" type="error" class="mb-4">{{error}}</VAlert>
<VRow><VCol v-for="item in facilities" :key="item.id" cols="12" md="6" xl="4"><VCard><VCardTitle>{{item.name}}</VCardTitle><VCardSubtitle>{{item.venue.name}} · {{item.sport_code?.name||'Central'}}</VCardSubtitle><VCardText><VChip v-for="tag in item.tags" :key="tag.id" class="mr-1" size="small">{{tag.name}}</VChip><p class="mt-3">{{item.description}}</p><p>{{item.opening_hours.length}} opening window(s)</p></VCardText><VCardActions><VBtn variant="text" @click="edit(item)">Edit</VBtn><VBtn variant="text" @click="selected=item;hoursOpen=true">Add hours</VBtn></VCardActions></VCard></VCol></VRow>
<VDialog v-model="open" max-width="800"><VCard><VCardTitle class="pa-6">{{selected?'Edit':'Add'}} facility</VCardTitle><VCardText><VRow><VCol cols="12" md="6"><VTextField v-model="form.name" label="Name"/></VCol><VCol cols="12" md="6"><VTextField v-model="form.code" label="Unique code"/></VCol><VCol cols="12" md="6"><VSelect v-model="form.venue_id" :items="meta.venues" item-title="name" item-value="id" label="Venue"/></VCol><VCol cols="12" md="6"><VSelect v-model="form.sport_code_id" :items="meta.sport_codes" item-title="name" item-value="id" label="Sport code"/></VCol><VCol cols="12" md="6"><VSelect v-model="form.facility_group_id" :items="meta.groups" item-title="name" item-value="id" label="Group"/></VCol><VCol cols="12" md="6"><VSelect v-model="form.facility_type" :items="['tennis_court','padel_court','squash_court','netball_court','field','hall','other']" label="Type"/></VCol><VCol cols="12"><VSelect v-model="form.tag_ids" :items="meta.tags" item-title="name" item-value="id" label="Tags" multiple chips/></VCol><VCol cols="12"><VTextarea v-model="form.description" label="Description"/></VCol><VCol cols="6"><VSwitch v-model="form.publicly_visible" label="Publicly visible"/></VCol><VCol cols="6"><VSwitch v-model="form.bookable" label="Bookable"/></VCol></VRow></VCardText><VCardActions><VSpacer/><VBtn variant="tonal" @click="open=false">Cancel</VBtn><VBtn @click="save">Save</VBtn></VCardActions></VCard></VDialog>
<VDialog v-model="hoursOpen" max-width="550"><VCard><VCardTitle class="pa-6">Add opening window</VCardTitle><VCardText><VSelect v-model="hours.day_of_week" :items="[{title:'Sunday',value:0},{title:'Monday',value:1},{title:'Tuesday',value:2},{title:'Wednesday',value:3},{title:'Thursday',value:4},{title:'Friday',value:5},{title:'Saturday',value:6}]" label="Day"/><VRow><VCol><VTextField v-model="hours.opens_at" type="time" label="Opens"/></VCol><VCol><VTextField v-model="hours.closes_at" type="time" label="Closes"/></VCol></VRow></VCardText><VCardActions><VSpacer/><VBtn @click="saveHours">Add window</VBtn></VCardActions></VCard></VDialog></div></template>
